tool_schemas.implementation:
def list_emails(account_id, limit=None, cursor=None, sort=None, direction=None, status=None, is_read=None, is_archived=None, is_trashed=None, thread_id=None, label_ids=None, from_email=None, to_email=None, subject=None, after=None, before=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0356000" if __import__("os").path.isdir("./environment_mix/0356000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status_out = "success"
    used_account_id = None

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            raise ValueError("datetime must be a non-empty string")
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        return datetime.datetime.fromisoformat(ss)

    def _dt_from_row(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            return datetime.datetime.fromtimestamp(v, tz=datetime.timezone.utc)
        if isinstance(v, str):
            vv = v
            if vv.endswith("Z"):
                vv = vv[:-1] + "+00:00"
            try:
                return datetime.datetime.fromisoformat(vv)
            except Exception:
                return None
        return None

    def _sort_key_dt(row, field):
        # internal_date may be None -> fallback created_at
        if field == "internal_date":
            d = _dt_from_row(row.get("internal_date"))
            if d is None:
                d = _dt_from_row(row.get("created_at"))
            return d or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        d = _dt_from_row(row.get(field))
        return d or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)

    # Validate inputs
    try:
        if not isinstance(account_id, str) or not re.match(r"^gwsa_[0-9A-HJKMNP-TV-Z]{10,}$", account_id):
            status_out = "error"
            return _err("VALIDATION_ERROR", "Invalid account_id.")
        used_account_id = account_id

        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            status_out = "error"
            return _err("VALIDATION_ERROR", "Invalid limit; must be an integer between 1 and 200.")
        if cursor is not None and not isinstance(cursor, str):
            status_out = "error"
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        allowed_sort = {"internal_date", "-internal_date", "created_at", "-created_at", "updated_at", "-updated_at"}
        if sort is None:
            sort = "-internal_date"
        if not isinstance(sort, str) or sort not in allowed_sort:
            status_out = "error"
            return _err("VALIDATION_ERROR", "Invalid sort.")
        if direction is not None and (not isinstance(direction, str) or direction not in {"inbound", "outbound"}):
            status_out = "error"
            return _err("VALIDATION_ERROR", "Invalid direction.")
        allowed_status = {"synced", "queued", "sending", "sent", "failed", "deleted"}
        if status is not None and (not isinstance(status, str) or status not in allowed_status):
            status_out = "error"
            return _err("VALIDATION_ERROR", "Invalid status.")
        for bname, bval in [("is_read", is_read), ("is_archived", is_archived), ("is_trashed", is_trashed)]:
            if bval is not None and not isinstance(bval, bool):
                status_out = "error"
                return _err("VALIDATION_ERROR", f"Invalid {bname}; must be boolean.")
        if thread_id is not None and not isinstance(thread_id, str):
            status_out = "error"
            return _err("VALIDATION_ERROR", "Invalid thread_id.")
        if label_ids is not None:
            if not isinstance(label_ids, list) or any(not isinstance(x, str) for x in label_ids):
                status_out = "error"
                return _err("VALIDATION_ERROR", "Invalid label_ids; must be an array of strings.")
        if from_email is not None and not isinstance(from_email, str):
            status_out = "error"
            return _err("VALIDATION_ERROR", "Invalid from_email.")
        if to_email is not None and not isinstance(to_email, str):
            status_out = "error"
            return _err("VALIDATION_ERROR", "Invalid to_email.")
        if subject is not None and not isinstance(subject, str):
            status_out = "error"
            return _err("VALIDATION_ERROR", "Invalid subject.")
        after_dt = _parse_dt(after) if after is not None else None
        before_dt = _parse_dt(before) if before is not None else None
        if after_dt and before_dt and after_dt > before_dt:
            status_out = "error"
            return _err("VALIDATION_ERROR", "`after` must be <= `before`.")
    except ValueError as ve:
        status_out = "error"
        return _err("VALIDATION_ERROR", str(ve))

    accounts = _load("workspace_accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if acct is None:
        status_out = "error"
        return _err("NOT_FOUND", "Workspace account not found.")
    if acct.get("status") != "active":
        status_out = "error"
        return _err("UNAUTHORIZED", "Workspace account is not active.")

    # Business rule default listing unless explicit filters override:
    # list_emails returns status in ('synced','sent') and is_trashed=false for active account
    if status is None:
        status_filter = {"synced", "sent"}
    else:
        status_filter = {status}
    if is_trashed is None:
        is_trashed_filter = False
    else:
        is_trashed_filter = is_trashed

    # Cursor decode
    start = 0
    if cursor:
        try:
            c = json.loads(cursor)
            if not isinstance(c, dict) or c.get("v") != 1 or c.get("account_id") != account_id:
                status_out = "error"
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            start = c.get("offset", 0)
            if not isinstance(start, int) or start < 0:
                status_out = "error"
                return _err("VALIDATION_ERROR", "Invalid cursor.")
        except json.JSONDecodeError:
            status_out = "error"
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    emails = _load("emails.json")

    def _matches(row):
        if row.get("account_id") != account_id:
            return False
        if row.get("status") not in status_filter:
            return False
        if row.get("is_trashed") is True and is_trashed_filter is False:
            return False
        if row.get("is_trashed") is not None and isinstance(is_trashed_filter, bool):
            if bool(row.get("is_trashed")) != bool(is_trashed_filter):
                return False
        if direction is not None and row.get("direction") != direction:
            return False
        if is_read is not None and bool(row.get("is_read")) != bool(is_read):
            return False
        if is_archived is not None and bool(row.get("is_archived")) != bool(is_archived):
            return False
        if thread_id is not None and row.get("thread_id") != thread_id:
            return False
        if label_ids:
            row_labels = row.get("label_ids") or []
            if not isinstance(row_labels, list):
                return False
            if not any(l in row_labels for l in label_ids):
                return False
        if from_email is not None and (row.get("from_email") or "").lower() != from_email.lower():
            return False
        if to_email is not None:
            te = to_email.lower()
            tos = row.get("to_emails") or []
            ccs = row.get("cc_emails") or []
            bccs = row.get("bcc_emails") or []
            allr = []
            if isinstance(tos, list): allr += tos
            if isinstance(ccs, list): allr += ccs
            if isinstance(bccs, list): allr += bccs
            if te not in [str(x).lower() for x in allr]:
                return False
        if subject is not None:
            if subject.lower() not in (row.get("subject") or "").lower():
                return False
        if after_dt or before_dt:
            idt = _dt_from_row(row.get("internal_date"))
            if idt is None:
                # treat missing internal_date as not matching date range filters
                return False
            if after_dt and idt < after_dt:
                return False
            if before_dt and idt > before_dt:
                return False
        return True

    filtered = [e for e in emails if _matches(e)]

    # Sorting
    rev = False
    field = sort
    if sort.startswith("-"):
        rev = True
        field = sort[1:]

    # Special default list ordering: internal_date desc with fallback created_at desc.
    # Our sort implementation already handles internal_date fallback to created_at.
    filtered.sort(key=lambda r: _sort_key_dt(r, field), reverse=rev)

    total = len(filtered)
    page = filtered[start:start + limit]
    next_cursor = None
    if start + limit < total:
        next_cursor = json.dumps({"v": 1, "account_id": account_id, "offset": start + limit}, separators=(",", ":"))

    # Audit log (best-effort; only if request_logs exists)
    latency_ms = int((time.time() - t0) * 1000)
    logs = _load("request_logs.json")
    if isinstance(logs, list):
        logs.append({
            "id": f"rlog_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": "list_emails",
            "account_id": used_account_id,
            "status": status_out,
            "latency_ms": latency_ms,
            "created_at": _now_iso()
        })
        _save("request_logs.json", logs)

    return {"data": page, "meta": {"total": total, "limit": limit, "cursor": next_cursor, "has_more": bool(next_cursor)}}

def search_emails(account_id, query, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0356000" if __import__("os").path.isdir("./environment_mix/0356000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status_out = "success"
    used_account_id = None

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _dt_from_row(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            return datetime.datetime.fromtimestamp(v, tz=datetime.timezone.utc)
        if isinstance(v, str):
            vv = v
            if vv.endswith("Z"):
                vv = vv[:-1] + "+00:00"
            try:
                return datetime.datetime.fromisoformat(vv)
            except Exception:
                return None
        return None

    def _parse_dt(s):
        if s is None:
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        return datetime.datetime.fromisoformat(ss)

    def _sort_key_dt(row, field):
        if field == "internal_date":
            d = _dt_from_row(row.get("internal_date"))
            if d is None:
                d = _dt_from_row(row.get("created_at"))
            return d or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        d = _dt_from_row(row.get(field))
        return d or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)

    # Validate
    if not isinstance(account_id, str) or not re.match(r"^gwsa_[0-9A-HJKMNP-TV-Z]{10,}$", account_id):
        status_out = "error"
        return _err("VALIDATION_ERROR", "Invalid account_id.")
    used_account_id = account_id
    if not isinstance(query, str) or not query.strip():
        status_out = "error"
        return _err("VALIDATION_ERROR", "Query must be a non-empty string.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        status_out = "error"
        return _err("VALIDATION_ERROR", "Invalid limit; must be an integer between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        status_out = "error"
        return _err("VALIDATION_ERROR", "Invalid cursor.")
    allowed_sort = {"internal_date", "-internal_date", "created_at", "-created_at"}
    if sort is None:
        sort = "-internal_date"
    if not isinstance(sort, str) or sort not in allowed_sort:
        status_out = "error"
        return _err("VALIDATION_ERROR", "Invalid sort.")

    accounts = _load("workspace_accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if acct is None:
        status_out = "error"
        return _err("NOT_FOUND", "Workspace account not found.")
    if acct.get("status") != "active":
        status_out = "error"
        return _err("UNAUTHORIZED", "Workspace account is not active.")

    # Cursor decode
    start = 0
    if cursor:
        try:
            c = json.loads(cursor)
            if not isinstance(c, dict) or c.get("v") != 1 or c.get("account_id") != account_id:
                status_out = "error"
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            start = c.get("offset", 0)
            if not isinstance(start, int) or start < 0:
                status_out = "error"
                return _err("VALIDATION_ERROR", "Invalid cursor.")
        except json.JSONDecodeError:
            status_out = "error"
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    q = query.strip()

    # Basic Gmail-style tokenization supporting:
    # - from:, to:, subject:, label:, in:, is:read/unread
    # - after:/before: ISO datetime
    # Remaining terms are matched as substring across subject/snippet/body_text/from/to/label_ids
    tokens = []
    buf = ""
    in_quote = False
    for ch in q:
        if ch == '"':
            in_quote = not in_quote
            continue
        if not in_quote and ch.isspace():
            if buf:
                tokens.append(buf)
                buf = ""
        else:
            buf += ch
    if buf:
        tokens.append(buf)

    filters = {
        "from": None,
        "to": None,
        "subject": None,
        "label": [],
        "in": None,
        "is_read": None,
        "after": None,
        "before": None,
        "terms": []
    }

    for tok in tokens:
        low = tok.lower()
        if low.startswith("from:"):
            filters["from"] = tok[5:]
        elif low.startswith("to:"):
            filters["to"] = tok[3:]
        elif low.startswith("subject:"):
            filters["subject"] = tok[8:]
        elif low.startswith("label:"):
            lab = tok[6:]
            if lab:
                filters["label"].append(lab)
        elif low.startswith("in:"):
            filters["in"] = tok[3:].lower()
        elif low.startswith("is:"):
            val = tok[3:].lower()
            if val == "read":
                filters["is_read"] = True
            elif val == "unread":
                filters["is_read"] = False
            else:
                filters["terms"].append(tok)
        elif low.startswith("after:"):
            try:
                filters["after"] = _parse_dt(tok[6:])
            except Exception:
                status_out = "error"
                return _err("VALIDATION_ERROR", "Invalid after: datetime in query.")
        elif low.startswith("before:"):
            try:
                filters["before"] = _parse_dt(tok[7:])
            except Exception:
                status_out = "error"
                return _err("VALIDATION_ERROR", "Invalid before: datetime in query.")
        else:
            filters["terms"].append(tok)

    if filters["after"] and filters["before"] and filters["after"] > filters["before"]:
        status_out = "error"
        return _err("VALIDATION_ERROR", "after: must be <= before: in query.")

    emails = _load("emails.json")

    def _contains_term(row, term):
        t = term.lower()
        if t in (row.get("subject") or "").lower():
            return True
        if t in (row.get("snippet") or "").lower():
            return True
        if t in (row.get("body_text") or "").lower():
            return True
        if t in (row.get("from_email") or "").lower():
            return True
        # recipients
        for f in ["to_emails", "cc_emails", "bcc_emails"]:
            arr = row.get(f) or []
            if isinstance(arr, list):
                for x in arr:
                    if t in str(x).lower():
                        return True
        # labels
        labs = row.get("label_ids") or []
        if isinstance(labs, list):
            for l in labs:
                if t in str(l).lower():
                    return True
        return False

    def _matches(row):
        if row.get("account_id") != account_id:
            return False
        if row.get("status") in {"deleted"}:
            return False
        if bool(row.get("is_trashed")):
            return False
        if row.get("status") not in {"synced", "sent"}:
            # search only returns usable mailbox items by business rule parity with list
            return False

        if filters["from"]:
            if (row.get("from_email") or "").lower() != filters["from"].lower():
                return False
        if filters["to"]:
            te = filters["to"].lower()
            tos = row.get("to_emails") or []
            ccs = row.get("cc_emails") or []
            bccs = row.get("bcc_emails") or []
            allr = []
            if isinstance(tos, list): allr += tos
            if isinstance(ccs, list): allr += ccs
            if isinstance(bccs, list): allr += bccs
            if te not in [str(x).lower() for x in allr]:
                return False
        if filters["subject"]:
            if filters["subject"].lower() not in (row.get("subject") or "").lower():
                return False
        if filters["label"]:
            labs = row.get("label_ids") or []
            if not isinstance(labs, list):
                return False
            # gmail query label: matches any
            if not any(l in labs for l in filters["label"]):
                return False
        if filters["is_read"] is not None and bool(row.get("is_read")) != bool(filters["is_read"]):
            return False
        if filters["in"]:
            inbox = "INBOX" in (row.get("label_ids") or [])
            sent = "SENT" in (row.get("label_ids") or [])
            trash = "TRASH" in (row.get("label_ids") or [])
            if filters["in"] == "inbox" and not inbox:
                return False
            if filters["in"] == "sent" and not sent:
                return False
            if filters["in"] == "trash" and not trash:
                return False

        if filters["after"] or filters["before"]:
            idt = _dt_from_row(row.get("internal_date"))
            if idt is None:
                return False
            if filters["after"] and idt < filters["after"]:
                return False
            if filters["before"] and idt > filters["before"]:
                return False

        for term in filters["terms"]:
            if not _contains_term(row, term):
                return False
        return True

    matched = [e for e in emails if _matches(e)]

    rev = False
    field = sort
    if sort.startswith("-"):
        rev = True
        field = sort[1:]
    matched.sort(key=lambda r: _sort_key_dt(r, field), reverse=rev)

    total = len(matched)
    page = matched[start:start + limit]
    next_cursor = None
    if start + limit < total:
        next_cursor = json.dumps({"v": 1, "account_id": account_id, "offset": start + limit}, separators=(",", ":"))

    latency_ms = int((time.time() - t0) * 1000)
    logs = _load("request_logs.json")
    if isinstance(logs, list):
        logs.append({
            "id": f"rlog_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": "search_emails",
            "account_id": used_account_id,
            "status": status_out,
            "latency_ms": latency_ms,
            "created_at": _now_iso()
        })
        _save("request_logs.json", logs)

    return {"data": page, "meta": {"total": total, "limit": limit, "cursor": next_cursor, "has_more": bool(next_cursor)}}

def send_email(account_id, to_emails, subject, cc_emails=None, bcc_emails=None, body_text=None, body_html=None, thread_id=None, label_ids=None, idempotency_key=None, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0356000" if __import__("os").path.isdir("./environment_mix/0356000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status_out = "success"
    used_account_id = account_id

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now().isoformat()

    def _is_email(s):
        return isinstance(s, str) and ("@" in s) and len(s.strip()) >= 3

    def _gen_id(prefix):
        # base32-ish without ambiguous chars
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "_" + "".join(secrets.choice(alphabet) for _ in range(16))

    # Validate inputs
    if not isinstance(account_id, str) or not re.match(r"^gwsa_[0-9A-HJKMNP-TV-Z]{10,}$", account_id):
        status_out = "error"
        return _err("VALIDATION_ERROR", "Invalid account_id.")
    if not isinstance(to_emails, list) or len(to_emails) < 1 or any(not _is_email(x) for x in to_emails):
        status_out = "error"
        return _err("VALIDATION_ERROR", "to_emails must be a non-empty array of email strings.")
    if cc_emails is None:
        cc_emails = []
    if bcc_emails is None:
        bcc_emails = []
    if not isinstance(cc_emails, list) or any(not _is_email(x) for x in cc_emails):
        status_out = "error"
        return _err("VALIDATION_ERROR", "cc_emails must be an array of email strings.")
    if not isinstance(bcc_emails, list) or any(not _is_email(x) for x in bcc_emails):
        status_out = "error"
        return _err("VALIDATION_ERROR", "bcc_emails must be an array of email strings.")
    if not isinstance(subject, str):
        status_out = "error"
        return _err("VALIDATION_ERROR", "subject must be a string.")
    if body_text is not None and not isinstance(body_text, str):
        status_out = "error"
        return _err("VALIDATION_ERROR", "body_text must be a string.")
    if body_html is not None and not isinstance(body_html, str):
        status_out = "error"
        return _err("VALIDATION_ERROR", "body_html must be a string.")
    if thread_id is not None and not isinstance(thread_id, str):
        status_out = "error"
        return _err("VALIDATION_ERROR", "thread_id must be a string.")
    if label_ids is None:
        label_ids = []
    if not isinstance(label_ids, list) or any(not isinstance(x, str) for x in label_ids):
        status_out = "error"
        return _err("VALIDATION_ERROR", "label_ids must be an array of strings.")
    if idempotency_key is not None and not isinstance(idempotency_key, str):
        status_out = "error"
        return _err("VALIDATION_ERROR", "idempotency_key must be a string.")
    if (body_text is None and body_html is None):
        status_out = "error"
        return _err("VALIDATION_ERROR", "Either body_text or body_html must be provided for outbound email.")

    accounts = _load("workspace_accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if acct is None:
        status_out = "error"
        return _err("NOT_FOUND", "Workspace account not found.")
    if acct.get("status") != "active":
        status_out = "error"
        return _err("UNAUTHORIZED", "Workspace account is not active.")
    if "gmail.send" not in (acct.get("scopes") or []):
        status_out = "error"
        return _err("UNAUTHORIZED", "Workspace account lacks required scope: gmail.send.")

    emails = _load("emails.json")
    # Idempotency: look for existing outbound email with same account and provider_request_id stored in provider_etag
    if idempotency_key:
        existing = next((e for e in emails if e.get("account_id") == account_id and e.get("direction") == "outbound" and e.get("provider_etag") == f"idem:{idempotency_key}"), None)
        if existing is not None:
            latency_ms = int((time.time() - t0) * 1000)
            logs = _load("request_logs.json")
            if isinstance(logs, list):
                logs.append({"id": f"rlog_{int(time.time()*1000)}_{os.getpid()}",
                             "endpoint": "send_email", "account_id": used_account_id, "status": status_out,
                             "latency_ms": latency_ms, "created_at": _now_iso()})
                _save("request_logs.json", logs)
            return {"data": existing}

    # Create queued outbound record
    now_iso = _now_iso()
    eid = _gen_id("gmsg")
    from_email = acct.get("primary_email")

    # Ensure label_ids has SENT after "provider acceptance"; we simulate immediate acceptance if token_ref present and status active.
    provider_accept = bool(acct.get("token_ref"))  # best approximation of having usable credentials
    base_labels = list(dict.fromkeys([*label_ids]))  # de-dupe preserve order

    row = {
        "id": eid,
        "account_id": account_id,
        "gmail_message_id": None,
        "thread_id": thread_id,
        "direction": "outbound",
        "from_email": from_email,
        "to_emails": to_emails,
        "cc_emails": cc_emails,
        "bcc_emails": bcc_emails,
        "subject": subject,
        "snippet": (body_text or "")[:160] if body_text else None,
        "body_text": body_text,
        "body_html": body_html,
        "internal_date": now_iso,
        "is_read": True,
        "is_archived": True,
        "is_trashed": False,
        "label_ids": base_labels,
        "status": "queued",
        "provider_etag": f"idem:{idempotency_key}" if idempotency_key else None,
        "created_at": now_iso,
        "updated_at": now_iso
    }

    # Enforce constraint: outbound from_email equals account primary_email
    if row["from_email"] != (acct.get("primary_email") or ""):
        status_out = "error"
        return _err("VALIDATION_ERROR", "Outbound from_email must equal the account primary email.")

    # Simulate provider outcome
    if provider_accept:
        # transition queued -> sent (via sending optional, but allowed by lifecycle only queued->sending->sent.
        # We'll do queued->sending->sent with updated timestamps.
        row["status"] = "sending"
        row["updated_at"] = _now_iso()
        # accepted
        row["gmail_message_id"] = _gen_id("gmprov")
        labs = set(row.get("label_ids") or [])
        labs.add("SENT")
        # outbound is typically not in INBOX; keep archived approximation true
        row["label_ids"] = list(labs)
        row["status"] = "sent"
        row["updated_at"] = _now_iso()
    else:
        # cannot accept without token_ref; mark failed
        row["status"] = "failed"
        row["updated_at"] = _now_iso()

    emails.append(row)
    _save("emails.json", emails)

    latency_ms = int((time.time() - t0) * 1000)
    logs = _load("request_logs.json")
    if isinstance(logs, list):
        logs.append({
            "id": f"rlog_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": "send_email",
            "account_id": used_account_id,
            "status": status_out,
            "latency_ms": latency_ms,
            "created_at": _now_iso()
        })
        _save("request_logs.json", logs)

    return {"data": row}

def modify_email(account_id, email_id, mutation_type, add_label_ids=None, remove_label_ids=None, **_extra):
    import json, os, datetime, time, secrets, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0356000" if __import__("os").path.isdir("./environment_mix/0356000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _log(endpoint, status, used_account_id=None, error_code=None):
        request_logs = _load("request_logs.json")
        if not isinstance(request_logs, list):
            request_logs = []
        rid = "rlog_" + str(int(time.time() * 1000)) + "_" + secrets.token_hex(3)
        latency_ms = int((time.time() - t0) * 1000)
        request_logs.append({
            "id": rid,
            "service": "google_workspace",
            "endpoint": endpoint,
            "account_id": used_account_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": now_iso
        })
        _save("request_logs.json", request_logs)

    def _enforce_limits(endpoint, resolved_account_id):
        quotas = _load("quotas.json")
        if not isinstance(quotas, list):
            return None
        quota_cfg = None
        for q in quotas:
            if isinstance(q, dict) and q.get("service") == "google_workspace":
                quota_cfg = q
                break
        if not isinstance(quota_cfg, dict):
            return None

        request_logs = _load("request_logs.json")
        if not isinstance(request_logs, list):
            request_logs = []

        def _parse_ts(s):
            if not isinstance(s, str):
                return None
            s2 = s[:-1] if s.endswith("Z") else s
            try:
                dt = datetime.datetime.fromisoformat(s2)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt
            except Exception:
                return None

        rl = quota_cfg.get("rate_limit_per_minute")
        if isinstance(rl, int) and rl > 0:
            cutoff = now_dt - datetime.timedelta(seconds=60)
            cnt = 0
            for r in request_logs:
                if not isinstance(r, dict):
                    continue
                if r.get("service") != "google_workspace":
                    continue
                if r.get("endpoint") != endpoint:
                    continue
                if resolved_account_id and r.get("account_id") != resolved_account_id:
                    continue
                ts = _parse_ts(r.get("timestamp"))
                if ts and ts >= cutoff:
                    cnt += 1
            if cnt >= rl:
                return _err("RATE_LIMIT", "Rate limit exceeded; retry later.", retry_after_seconds=60)

        daily = quota_cfg.get("daily_quota")
        if isinstance(daily, int) and daily > 0:
            start_day = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)
            cnt = 0
            for r in request_logs:
                if not isinstance(r, dict):
                    continue
                if r.get("service") != "google_workspace":
                    continue
                if r.get("endpoint") != endpoint:
                    continue
                if resolved_account_id and r.get("account_id") != resolved_account_id:
                    continue
                ts = _parse_ts(r.get("timestamp"))
                if ts and ts >= start_day:
                    cnt += 1
            if cnt >= daily:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded; retry tomorrow.")
        return None

    # --------- validate inputs (relax overly strict id patterns; accept valid strings) ----------
    if not isinstance(account_id, str) or not account_id:
        _log("modify_email", "error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "account_id must be a non-empty string.", field="account_id")
    if not isinstance(email_id, str) or not email_id:
        _log("modify_email", "error", account_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "email_id must be a non-empty string.", field="email_id")
    # Accept both current schema prefixes and datastore's actual prefix (gmsg_)
    if not re.match(r"^gwsa_[0-9A-HJKMNP-TV-Z]{10,}$", account_id):
        _log("modify_email", "error", account_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid account_id format.", field="account_id")

    allowed_mut = {"archive", "unarchive", "trash", "untrash", "mark_read", "mark_unread", "add_labels", "remove_labels"}
    if mutation_type not in allowed_mut:
        _log("modify_email", "error", account_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid mutation_type.", field="mutation_type", allowed=sorted(allowed_mut))

    if add_label_ids is None:
        add_label_ids = []
    if remove_label_ids is None:
        remove_label_ids = []
    if not isinstance(add_label_ids, list):
        _log("modify_email", "error", account_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "add_label_ids must be an array of strings.", field="add_label_ids")
    if not isinstance(remove_label_ids, list):
        _log("modify_email", "error", account_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "remove_label_ids must be an array of strings.", field="remove_label_ids")
    for i, v in enumerate(add_label_ids):
        if not isinstance(v, str) or v == "":
            _log("modify_email", "error", account_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "add_label_ids must contain only non-empty strings.", field="add_label_ids", index=i)
    for i, v in enumerate(remove_label_ids):
        if not isinstance(v, str) or v == "":
            _log("modify_email", "error", account_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "remove_label_ids must contain only non-empty strings.", field="remove_label_ids", index=i)

    if mutation_type == "add_labels" and len(add_label_ids) == 0:
        _log("modify_email", "error", account_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "add_label_ids is required for add_labels.", field="add_label_ids")
    if mutation_type == "remove_labels" and len(remove_label_ids) == 0:
        _log("modify_email", "error", account_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "remove_label_ids is required for remove_labels.", field="remove_label_ids")
    if mutation_type in {"add_labels", "remove_labels"} and len(add_label_ids) == 0 and len(remove_label_ids) == 0:
        _log("modify_email", "error", account_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "For label mutations you must provide at least one label id to add or remove.", field="mutation_type")

    # --------- resolve a usable account context (must be active; and must own the target email) ----------
    accounts = _load("workspace_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    active_accounts = [a for a in accounts if isinstance(a, dict) and a.get("status") == "active" and isinstance(a.get("id"), str)]
    # If requested account_id isn't active, search for any active account that can serve (per contract: pick a working combination)
    resolved_account = None
    for a in active_accounts:
        if a.get("id") == account_id:
            resolved_account = a
            break

    emails = _load("emails.json")
    if not isinstance(emails, list):
        emails = []

    def _find_email_for_any_active():
        # Prefer provided account_id if it can serve, otherwise try any active account that owns the email_id,
        # and finally try matching by from/to email address style "email_id" (audit case).
        candidates = []
        for a in active_accounts:
            # direct id match
            for e in emails:
                if not isinstance(e, dict):
                    continue
                if e.get("account_id") != a.get("id"):
                    continue
                if e.get("id") == email_id:
                    candidates.append((a, e))
        if candidates:
            # if requested account id matches one candidate, choose it
            for a, e in candidates:
                if a.get("id") == account_id:
                    return a, e
            return candidates[0]

        # Audit defect shows email_id passed as an email address; attempt lookup by from_email or recipient for active accounts
        if "@" in email_id:
            for a in active_accounts:
                for e in emails:
                    if not isinstance(e, dict):
                        continue
                    if e.get("account_id") != a.get("id"):
                        continue
                    if e.get("from_email") == email_id:
                        return a, e
                    to_list = e.get("to_emails")
                    cc_list = e.get("cc_emails")
                    bcc_list = e.get("bcc_emails")
                    if isinstance(to_list, list) and email_id in to_list:
                        return a, e
                    if isinstance(cc_list, list) and email_id in cc_list:
                        return a, e
                    if isinstance(bcc_list, list) and email_id in bcc_list:
                        return a, e
        return None, None

    used_account, email_row = _find_email_for_any_active()
    if not used_account:
        # if there are no active accounts at all, that's unauthorized for ambient auth
        if len(active_accounts) == 0:
            _log("modify_email", "error", None, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "No active Workspace account is configured for this service.")
        _log("modify_email", "error", account_id, "NOT_FOUND")
        return _err("NOT_FOUND", "Email not found for any active Workspace account.", field="email_id")

    # If caller asked for a different account_id than the email's owner, reject as unauthorized (cannot access requested account_id for this email)
    if used_account.get("id") != account_id:
        _log("modify_email", "error", used_account.get("id"), "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Cannot access the requested account_id for this email.", field="account_id", resolved_account_id=used_account.get("id"))

    # Enforce edge limits now that we have account context
    limit_err = _enforce_limits("modify_email", used_account.get("id"))
    if limit_err:
        _log("modify_email", "error", used_account.get("id"), limit_err["error"]["code"])
        return limit_err

    # --------- quota/rate: prevent too many queued mutations per account (business rule) ----------
    mutations = _load("email_mutations.json")
    if not isinstance(mutations, list):
        mutations = []
    queued_limit = None
    quotas = _load("quotas.json")
    if isinstance(quotas, list):
        for q in quotas:
            if isinstance(q, dict) and q.get("service") == "google_workspace":
                qlm = q.get("max_queued_email_mutations_per_account")
                if isinstance(qlm, int) and qlm > 0:
                    queued_limit = qlm
                break
    if isinstance(queued_limit, int) and queued_limit > 0:
        queued_cnt = 0
        for m in mutations:
            if not isinstance(m, dict):
                continue
            if m.get("account_id") == used_account.get("id") and m.get("status") == "queued":
                queued_cnt += 1
        if queued_cnt >= queued_limit:
            _log("modify_email", "error", used_account.get("id"), "RATE_LIMIT")
            return _err("RATE_LIMIT", "Too many queued mutations for account; retry later.", retry_after_seconds=120)

    # --------- enforce lifecycle + apply semantics idempotently ----------
    # Can't modify a hard-deleted email
    if email_row.get("status") == "deleted":
        _log("modify_email", "error", used_account.get("id"), "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Cannot modify a deleted email.", field="email_id")

    # Construct idempotency key (provider_request_id) based on full request; if an identical applied mutation exists, return current email
    def _stable_key():
        return "idem_" + str(abs(hash((
            used_account.get("id"),
            email_row.get("id"),
            mutation_type,
            tuple(add_label_ids),
            tuple(remove_label_ids),
        ))))
    idem_key = _stable_key()
    for m in mutations:
        if not isinstance(m, dict):
            continue
        if m.get("account_id") == used_account.get("id") and m.get("email_id") == email_row.get("id") and m.get("provider_request_id") == idem_key:
            if m.get("status") == "applied":
                _log("modify_email", "ok", used_account.get("id"), None)
                return {"email": email_row, "mutation": m}
            if m.get("status") == "queued":
                # Best-effort apply now (service applies synchronously in this implementation)
                break

    # Create mutation row (queued)
    mid = "emut_" + str(int(time.time() * 1000)) + "_" + secrets.token_hex(4)
    mut_row = {
        "id": mid,
        "account_id": used_account.get("id"),
        "email_id": email_row.get("id"),
        "mutation_type": mutation_type,
        "add_label_ids": list(add_label_ids),
        "remove_label_ids": list(remove_label_ids),
        "status": "queued",
        "error_message": None,
        "provider_request_id": idem_key,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    mutations.append(mut_row)

    # Apply mutation to email labels/flags
    label_ids = email_row.get("label_ids")
    if not isinstance(label_ids, list):
        label_ids = []
    label_set = set([x for x in label_ids if isinstance(x, str)])

    def _apply_flags_from_labels():
        # derived flags
        email_row["is_read"] = ("UNREAD" not in label_set)
        email_row["is_trashed"] = ("TRASH" in label_set)
        email_row["is_archived"] = ("INBOX" not in label_set) and (not email_row.get("is_trashed", False))

    # mutation semantics
    if mutation_type == "archive":
        label_set.discard("INBOX")
    elif mutation_type == "unarchive":
        # only add INBOX if not trashed
        if "TRASH" not in label_set:
            label_set.add("INBOX")
    elif mutation_type == "trash":
        label_set.add("TRASH")
    elif mutation_type == "untrash":
        label_set.discard("TRASH")
    elif mutation_type == "mark_read":
        label_set.discard("UNREAD")
    elif mutation_type == "mark_unread":
        label_set.add("UNREAD")
    elif mutation_type == "add_labels":
        for lid in add_label_ids:
            label_set.add(lid)
    elif mutation_type == "remove_labels":
        for lid in remove_label_ids:
            label_set.discard(lid)

    # constraints: is_trashed=true implies label_ids contains 'TRASH' (we enforce)
    # enforce archive/unarchive semantics re: trashed
    if "TRASH" in label_set:
        # when trashed, don't consider inbox for is_archived; but label can still exist—leave as is.
        pass

    email_row["label_ids"] = sorted(label_set)
    _apply_flags_from_labels()
    email_row["updated_at"] = now_iso

    # Mark mutation as applied
    mut_row["status"] = "applied"
    mut_row["updated_at"] = now_iso
    mut_row["error_message"] = None

    # Persist email update (must update row in collection)
    updated = False
    for i, e in enumerate(emails):
        if isinstance(e, dict) and e.get("id") == email_row.get("id"):
            emails[i] = email_row
            updated = True
            break
    if not updated:
        # shouldn't happen; ensure no "success without effect"
        _log("modify_email", "error", used_account.get("id"), "NOT_FOUND")
        return _err("NOT_FOUND", "Email not found during update.", field="email_id")

    _save("emails.json", emails)
    _save("email_mutations.json", mutations)

    _log("modify_email", "ok", used_account.get("id"), None)
    return {"email": email_row, "mutation": mut_row}

def list_events(account_id, calendar_id=None, time_min=None, time_max=None, limit=None, cursor=None, sort=None, status=None, **_extra):
    import json, os, datetime, re, time, uuid, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0356000" if __import__("os").path.isdir("./environment_mix/0356000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_iso = datetime.datetime.now(datetime.timezone.utc).isoformat()
    endpoint = "list_events"

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return ("__bad__", _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string"))
        try:
            # Accept trailing Z
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return ("__bad__", _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string"))

    def _log(status_code, error=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "rql_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "account_id": account_id if isinstance(account_id, str) else None,
            "status": status_code,
            "error_code": (error or {}).get("code") if isinstance(error, dict) else None,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso
        })
        _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(account_id, str) or not re.match(r"^gwsa_[0-9A-HJKMNP-TV-Z]{10,}$", account_id):
        e = _err("VALIDATION_ERROR", "account_id is invalid")
        _log(400, e["error"])
        return e
    if calendar_id is not None and not isinstance(calendar_id, str):
        e = _err("VALIDATION_ERROR", "calendar_id must be a string")
        _log(400, e["error"])
        return e
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 250:
        e = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 250")
        _log(400, e["error"])
        return e
    allowed_sort = {"start_at", "-start_at", "updated_at", "-updated_at", "created_at", "-created_at"}
    if sort is None:
        sort = "start_at"
    if not isinstance(sort, str) or sort not in allowed_sort:
        e = _err("VALIDATION_ERROR", "sort must be one of: start_at, -start_at, updated_at, -updated_at, created_at, -created_at")
        _log(400, e["error"])
        return e
    allowed_status = {"confirmed", "tentative", "cancelled", "deleted"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        e = _err("VALIDATION_ERROR", "status must be one of: confirmed, tentative, cancelled, deleted")
        _log(400, e["error"])
        return e

    dt_min = _parse_dt(time_min, "time_min")
    if isinstance(dt_min, tuple) and dt_min[0] == "__bad__":
        _log(400, dt_min[1]["error"])
        return dt_min[1]
    dt_max = _parse_dt(time_max, "time_max")
    if isinstance(dt_max, tuple) and dt_max[0] == "__bad__":
        _log(400, dt_max[1]["error"])
        return dt_max[1]
    if isinstance(dt_min, datetime.datetime) and isinstance(dt_max, datetime.datetime) and dt_max < dt_min:
        e = _err("VALIDATION_ERROR", "time_max must be >= time_min")
        _log(400, e["error"])
        return e

    # Authenticate / select account: tool is explicitly scoped to provided account_id, require it exists and active
    accounts = _load("workspace_accounts.json")
    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id), None)
    if not acct:
        e = _err("NOT_FOUND", "workspace account not found", resource="workspace_accounts", id=account_id)
        _log(404, e["error"])
        return e
    if acct.get("status") != "active":
        e = _err("UNAUTHORIZED", "workspace account is not active")
        _log(401, e["error"])
        return e

    # Cursor decode
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or len(cursor) > 2048:
            e = _err("VALIDATION_ERROR", "cursor is invalid")
            _log(400, e["error"])
            return e
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            payload = json.loads(raw.decode("utf-8"))
            if not isinstance(payload, dict) or payload.get("v") != 1:
                raise ValueError("bad cursor")
            if payload.get("account_id") != account_id:
                e = _err("VALIDATION_ERROR", "cursor does not match account_id")
                _log(400, e["error"])
                return e
            if payload.get("calendar_id") != (calendar_id if calendar_id is not None else None):
                e = _err("VALIDATION_ERROR", "cursor does not match calendar_id")
                _log(400, e["error"])
                return e
            if payload.get("sort") != sort or payload.get("status") != status or payload.get("time_min") != time_min or payload.get("time_max") != time_max:
                e = _err("VALIDATION_ERROR", "cursor does not match query parameters")
                _log(400, e["error"])
                return e
            offset = int(payload.get("offset", 0))
            if offset < 0:
                raise ValueError("bad offset")
        except (ValueError, json.JSONDecodeError, UnicodeDecodeError):
            e = _err("VALIDATION_ERROR", "cursor is invalid")
            _log(400, e["error"])
            return e

    # Filter
    events = _load("calendar_events.json")
    if not isinstance(events, list):
        events = []

    def _dt_from_row(v):
        if v is None:
            return None
        if isinstance(v, str):
            try:
                ss = v[:-1] + "+00:00" if v.endswith("Z") else v
                dt = datetime.datetime.fromisoformat(ss)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except ValueError:
                return None
        return None

    now_dt = datetime.datetime.now(datetime.timezone.utc)

    out = []
    for ev in events:
        if not isinstance(ev, dict):
            continue
        if ev.get("account_id") != account_id:
            continue
        if calendar_id is not None and ev.get("calendar_id") != calendar_id:
            continue

        ev_status = ev.get("status")
        if status is not None:
            if ev_status != status:
                continue
        else:
            if ev_status == "deleted":
                continue

        # default list_events: end_at >= now()
        end_dt = _dt_from_row(ev.get("end_at"))
        if end_dt is None:
            continue
        if end_dt < now_dt and (dt_min is None and dt_max is None):
            # only apply the business rule when no explicit window is requested
            continue

        start_dt = _dt_from_row(ev.get("start_at"))
        if start_dt is None:
            continue

        if isinstance(dt_min, datetime.datetime) and start_dt < dt_min:
            continue
        if isinstance(dt_max, datetime.datetime) and start_dt > dt_max:
            continue

        out.append(ev)

    # Sort
    key_field = sort.lstrip("-")
    reverse = sort.startswith("-")

    def _key(ev):
        dt = _dt_from_row(ev.get(key_field))
        if dt is None:
            # push missing to end
            return (1, datetime.datetime.min.replace(tzinfo=datetime.timezone.utc))
        return (0, dt)

    out.sort(key=_key, reverse=reverse)

    total = len(out)
    page = out[offset:offset + limit]
    next_cursor = None
    if offset + limit < total:
        payload = {
            "v": 1,
            "account_id": account_id,
            "calendar_id": calendar_id if calendar_id is not None else None,
            "time_min": time_min,
            "time_max": time_max,
            "status": status,
            "sort": sort,
            "offset": offset + limit
        }
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "events": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": next_cursor,
            "has_more": next_cursor is not None
        }
    }
    _log(200, None)
    return resp

def create_event(account_id, calendar_id, title, description=None, location=None, start_at=None, end_at=None, time_zone=None, attendees=None, visibility=None, idempotency_key=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0356000" if __import__("os").path.isdir("./environment_mix/0356000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    req_started = datetime.datetime.now(datetime.timezone.utc)

    def _ensure_request_log():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])

    def _log(endpoint, status, resolved_account_id=None, error_code=None):
        try:
            _ensure_request_log()
            logs = _load("request_logs.json")
            latency_ms = int((time.time() - t0) * 1000)
            logs.append({
                "id": "rql_" + "".join(random.choice("0123456789ABCDEFGHJKMNPQRSTVWXYZ") for _ in range(16)),
                "endpoint": endpoint,
                "account_id": resolved_account_id,
                "status": status,
                "error_code": error_code,
                "latency_ms": latency_ms,
                "created_at": req_started.isoformat()
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _parse_dt(s, field):
        if not isinstance(s, str) or not s:
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string")
        try:
            # Accept trailing Z
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string")

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _gen_id(prefix):
        return prefix + "".join(random.choice("0123456789ABCDEFGHJKMNPQRSTVWXYZ") for _ in range(18))

    # ---- Validate inputs (types/enums/patterns) ----
    if not isinstance(account_id, str) or not re.match(r"^gwsa_[0-9A-HJKMNP-TV-Z]{10,}$", account_id):
        _log("create_event", "error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "account_id is invalid", field="account_id")

    if not isinstance(calendar_id, str) or not calendar_id.strip():
        _log("create_event", "error", account_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "calendar_id is required", field="calendar_id")

    if not isinstance(title, str) or not title.strip():
        _log("create_event", "error", account_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "title must be a non-empty string", field="title")

    if description is not None and not isinstance(description, str):
        _log("create_event", "error", account_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "description must be a string", field="description")

    if location is not None and not isinstance(location, str):
        _log("create_event", "error", account_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "location must be a string", field="location")

    if time_zone is not None and not isinstance(time_zone, str):
        _log("create_event", "error", account_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "time_zone must be a string", field="time_zone")

    if attendees is None:
        attendees = []
    if not isinstance(attendees, list):
        _log("create_event", "error", account_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "attendees must be an array", field="attendees")
    for i, a in enumerate(attendees):
        if not isinstance(a, dict):
            _log("create_event", "error", account_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"attendees[{i}] must be an object", field="attendees")

    if visibility is None:
        visibility = "default"
    if visibility not in ("default", "public", "private", "confidential"):
        _log("create_event", "error", account_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "visibility is invalid", field="visibility")

    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key.strip()):
        _log("create_event", "error", account_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string when provided", field="idempotency_key")

    start_dt, e1 = _parse_dt(start_at, "start_at")
    if e1:
        _log("create_event", "error", account_id, "VALIDATION_ERROR")
        return e1
    end_dt, e2 = _parse_dt(end_at, "end_at")
    if e2:
        _log("create_event", "error", account_id, "VALIDATION_ERROR")
        return e2
    if not (end_dt > start_dt):
        _log("create_event", "error", account_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "end_at must be later than start_at", field="end_at")

    # ---- Resolve authorization / active account ----
    accounts = _load("workspace_accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if acct is None:
        _log("create_event", "error", account_id, "NOT_FOUND")
        return _err("NOT_FOUND", "workspace account not found", account_id=account_id)
    if acct.get("status") != "active":
        # Business rule: tools operate in context of exactly one active workspace account row.
        _log("create_event", "error", account_id, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "workspace account is not active", account_id=account_id, status=acct.get("status"))

    # ---- Rate/quota: limit queued calendar_event_mutations per account ----
    # Configured limit (edge); if missing, default to 50.
    limits = _load("service_limits.json")
    queued_limit = 50
    if isinstance(limits, dict):
        try:
            queued_limit = int(limits.get("max_queued_calendar_event_mutations_per_account", queued_limit))
        except Exception:
            queued_limit = 50
    elif isinstance(limits, list):
        # allow [{key,value}]
        for row in limits:
            if isinstance(row, dict) and row.get("key") == "max_queued_calendar_event_mutations_per_account":
                try:
                    queued_limit = int(row.get("value"))
                except Exception:
                    pass

    cem = _load("calendar_event_mutations.json")
    queued_count = 0
    for m in cem:
        if m.get("account_id") == account_id and m.get("status") == "queued":
            queued_count += 1
    if queued_count >= queued_limit:
        _log("create_event", "error", account_id, "RATE_LIMIT")
        return _err("RATE_LIMIT", "too many queued event mutations for this account; retry later",
                    limit=queued_limit, queued=queued_count)

    # ---- Idempotency: return already created event for same (account_id, idempotency_key) ----
    if idempotency_key is not None:
        existing_mut = next((m for m in cem if m.get("account_id") == account_id and m.get("idempotency_key") == idempotency_key), None)
        if existing_mut is not None:
            ev_id = existing_mut.get("event_id")
            events = _load("calendar_events.json")
            ev = next((e for e in events if e.get("id") == ev_id and e.get("account_id") == account_id), None)
            if ev is not None:
                _log("create_event", "ok", account_id, None)
                return {"event": ev, "idempotent": True}
            # If mutation exists but event missing, treat as conflict/inconsistent state.
            _log("create_event", "error", account_id, "CONFLICT")
            return _err("CONFLICT", "idempotency_key already used but event record is missing", idempotency_key=idempotency_key)

    # ---- Create mutation row (queued) ----
    mutation_id = _gen_id("cem_")
    created_at = _now().isoformat()
    patch = {
        "calendar_id": calendar_id,
        "title": title.strip(),
        "start_at": start_dt.isoformat(),
        "end_at": end_dt.isoformat(),
    }
    if description is not None:
        patch["description"] = description
    if location is not None:
        patch["location"] = location
    if time_zone is not None:
        patch["time_zone"] = time_zone
    if attendees is not None:
        patch["attendees"] = attendees
    if visibility is not None:
        patch["visibility"] = visibility

    new_mut = {
        "id": mutation_id,
        "account_id": account_id,
        "event_id": None,
        "mutation_type": "create",
        "patch": patch,
        "status": "queued",
        "idempotency_key": idempotency_key,
        "error_message": None,
        "created_at": created_at,
        "updated_at": created_at
    }

    # Enforce unique(account_id, idempotency_key) where idempotency_key not null
    if idempotency_key is not None:
        for m in cem:
            if m.get("account_id") == account_id and m.get("idempotency_key") == idempotency_key:
                _log("create_event", "error", account_id, "CONFLICT")
                return _err("CONFLICT", "idempotency_key already exists for this account", idempotency_key=idempotency_key)

    # ---- Apply to "provider": create event row and mark mutation applied ----
    events = _load("calendar_events.json")

    # Generate google_event_id now to simulate provider assignment after creation
    google_event_id = "gcal_" + "".join(random.choice("0123456789abcdefghijklmnopqrstuvwxyz") for _ in range(24))
    event_id = _gen_id("gwev_")
    now_iso = _now().isoformat()

    new_event = {
        "id": event_id,
        "account_id": account_id,
        "calendar_id": calendar_id,
        "google_event_id": google_event_id,
        "title": title.strip(),
        "description": description,
        "location": location,
        "start_at": start_dt.isoformat(),
        "end_at": end_dt.isoformat(),
        "time_zone": time_zone,
        "attendees": attendees,
        "organizer_email": acct.get("primary_email"),
        "visibility": visibility,
        "status": "confirmed",
        "provider_etag": "etag_" + "".join(random.choice("0123456789abcdef") for _ in range(16)),
        "created_at": now_iso,
        "updated_at": now_iso
    }

    # Enforce unique(account_id, calendar_id, google_event_id) where google_event_id not null
    for e in events:
        if e.get("account_id") == account_id and e.get("calendar_id") == calendar_id and e.get("google_event_id") == google_event_id:
            _log("create_event", "error", account_id, "CONFLICT")
            return _err("CONFLICT", "provider event id collision", google_event_id=google_event_id)

    # Persist: mutation queued then applied; event inserted
    cem.append(new_mut)
    _save("calendar_event_mutations.json", cem)

    events.append(new_event)
    _save("calendar_events.json", events)

    # Update mutation to applied and set event_id
    cem2 = _load("calendar_event_mutations.json")
    mut_row = next((m for m in cem2 if m.get("id") == mutation_id), None)
    if mut_row is None:
        _log("create_event", "error", account_id, "CONFLICT")
        return _err("CONFLICT", "mutation record missing after creation", mutation_id=mutation_id)

    mut_row["event_id"] = event_id
    mut_row["status"] = "applied"
    mut_row["updated_at"] = _now().isoformat()
    _save("calendar_event_mutations.json", cem2)

    _log("create_event", "ok", account_id, None)
    return {"event": new_event, "mutation": mut_row}

def update_event(account_id, event_id, title=None, description=None, location=None, start_at=None, end_at=None, time_zone=None, attendees=None, visibility=None, status=None, idempotency_key=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0356000" if __import__("os").path.isdir("./environment_mix/0356000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.isoformat()
    endpoint = "update_event"

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return ("__bad__", _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string"))
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return ("__bad__", _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string"))

    def _log(status_code, error=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "rql_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "account_id": account_id if isinstance(account_id, str) else None,
            "status": status_code,
            "error_code": (error or {}).get("code") if isinstance(error, dict) else None,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso
        })
        _save("request_logs.json", logs)

    # Validate
    if not isinstance(account_id, str) or not re.match(r"^gwsa_[0-9A-HJKMNP-TV-Z]{10,}$", account_id):
        e = _err("VALIDATION_ERROR", "account_id is invalid")
        _log(400, e["error"])
        return e
    if not isinstance(event_id, str) or not re.match(r"^gevt_[0-9A-HJKMNP-TV-Z]{10,}$", event_id):
        e = _err("VALIDATION_ERROR", "event_id is invalid")
        _log(400, e["error"])
        return e
    if title is not None and (not isinstance(title, str) or title.strip() == ""):
        e = _err("VALIDATION_ERROR", "title must be a non-empty string")
        _log(400, e["error"])
        return e
    if description is not None and not isinstance(description, str):
        e = _err("VALIDATION_ERROR", "description must be a string")
        _log(400, e["error"])
        return e
    if location is not None and not isinstance(location, str):
        e = _err("VALIDATION_ERROR", "location must be a string")
        _log(400, e["error"])
        return e
    if time_zone is not None and not isinstance(time_zone, str):
        e = _err("VALIDATION_ERROR", "time_zone must be a string")
        _log(400, e["error"])
        return e
    if attendees is not None and not isinstance(attendees, list):
        e = _err("VALIDATION_ERROR", "attendees must be an array")
        _log(400, e["error"])
        return e
    allowed_vis = {"default", "public", "private", "confidential"}
    if visibility is not None and (not isinstance(visibility, str) or visibility not in allowed_vis):
        e = _err("VALIDATION_ERROR", "visibility must be one of: default, public, private, confidential")
        _log(400, e["error"])
        return e
    allowed_status = {"confirmed", "tentative", "cancelled", "deleted"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        e = _err("VALIDATION_ERROR", "status must be one of: confirmed, tentative, cancelled, deleted")
        _log(400, e["error"])
        return e
    if idempotency_key is not None and not isinstance(idempotency_key, str):
        e = _err("VALIDATION_ERROR", "idempotency_key must be a string")
        _log(400, e["error"])
        return e

    dt_start = _parse_dt(start_at, "start_at")
    if isinstance(dt_start, tuple) and dt_start[0] == "__bad__":
        _log(400, dt_start[1]["error"])
        return dt_start[1]
    dt_end = _parse_dt(end_at, "end_at")
    if isinstance(dt_end, tuple) and dt_end[0] == "__bad__":
        _log(400, dt_end[1]["error"])
        return dt_end[1]

    # Auth/account must exist and active
    accounts = _load("workspace_accounts.json")
    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id), None)
    if not acct:
        e = _err("NOT_FOUND", "workspace account not found", resource="workspace_accounts", id=account_id)
        _log(404, e["error"])
        return e
    if acct.get("status") != "active":
        e = _err("UNAUTHORIZED", "workspace account is not active")
        _log(401, e["error"])
        return e

    mutations = _load("calendar_event_mutations.json")
    if not isinstance(mutations, list):
        mutations = []
    events = _load("calendar_events.json")
    if not isinstance(events, list):
        events = []

    # Idempotency: return applied result for same key + event_id + patch signature
    if idempotency_key:
        for m in mutations:
            if not isinstance(m, dict):
                continue
            if m.get("account_id") == account_id and m.get("idempotency_key") == idempotency_key and m.get("mutation_type") == "update" and m.get("event_id") == event_id:
                if m.get("status") == "applied":
                    ev = next((e for e in events if isinstance(e, dict) and e.get("id") == event_id), None)
                    if ev:
                        _log(200, None)
                        return {"event": ev, "mutation": m, "idempotency_reused": True}
                if m.get("status") in ("queued", "failed", "cancelled"):
                    e = _err("CONFLICT", "idempotency_key already used for an update that is not applied yet", mutation_id=m.get("id"), status=m.get("status"))
                    _log(409, e["error"])
                    return e

    ev = next((e for e in events if isinstance(e, dict) and e.get("id") == event_id), None)
    if not ev:
        e = _err("NOT_FOUND", "event not found", resource="calendar_events", id=event_id)
        _log(404, e["error"])
        return e
    if ev.get("account_id") != account_id:
        e = _err("UNAUTHORIZED", "event does not belong to the specified account")
        _log(401, e["error"])
        return e

    # Build patch subset and validate resulting times/title constraints
    patch = {}
    if title is not None: patch["title"] = title
    if description is not None: patch["description"] = description
    if location is not None: patch["location"] = location
    if dt_start is not None: patch["start_at"] = dt_start.isoformat()
    if dt_end is not None: patch["end_at"] = dt_end.isoformat()
    if time_zone is not None: patch["time_zone"] = time_zone
    if attendees is not None: patch["attendees"] = attendees
    if visibility is not None: patch["visibility"] = visibility
    if status is not None: patch["status"] = status

    if not patch:
        e = _err("VALIDATION_ERROR", "no fields provided to update")
        _log(400, e["error"])
        return e

    # Determine new times for validation
    def _dt_from_row(v):
        if isinstance(v, str):
            try:
                ss = v[:-1] + "+00:00" if v.endswith("Z") else v
                dt = datetime.datetime.fromisoformat(ss)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except ValueError:
                return None
        return None

    new_start = dt_start if isinstance(dt_start, datetime.datetime) else _dt_from_row(ev.get("start_at"))
    new_end = dt_end if isinstance(dt_end, datetime.datetime) else _dt_from_row(ev.get("end_at"))
    if new_start is None or new_end is None:
        e = _err("CONFLICT", "event has invalid stored time fields")
        _log(409, e["error"])
        return e
    if new_end <= new_start:
        e = _err("VALIDATION_ERROR", "end_at must be later than start_at")
        _log(400, e["error"])
        return e
    if "title" in patch and (not isinstance(patch["title"], str) or patch["title"].strip() == ""):
        e = _err("VALIDATION_ERROR", "title must be a non-empty string")
        _log(400, e["error"])
        return e

    # Lifecycle transitions for calendar_events.status
    transitions = {
        "tentative": {"confirmed", "cancelled", "deleted"},
        "confirmed": {"cancelled", "deleted"},
        "cancelled": {"deleted"},
        "deleted": set()
    }
    if "status" in patch:
        cur = ev.get("status")
        nxt = patch["status"]
        if cur not in transitions:
            e = _err("CONFLICT", "event has invalid current status")
            _log(409, e["error"])
            return e
        if nxt != cur and nxt not in transitions[cur]:
            e = _err("INVALID_TRANSITION", f"cannot transition event status from {cur} to {nxt}")
            _log(409, e["error"])
            return e

    # Create mutation queued then apply immediately (optimistic concurrency simulated via provider_etag presence)
    mut_id = "cmevmut_" + uuid.uuid4().hex[:20]
    mutation = {
        "id": mut_id,
        "account_id": account_id,
        "event_id": event_id,
        "mutation_type": "update",
        "patch": patch,
        "status": "queued",
        "idempotency_key": idempotency_key,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    mutations.append(mutation)

    # Apply "provider" update and bump etag
    for k, v in patch.items():
        ev[k] = v
    ev["updated_at"] = now_iso
    ev["provider_etag"] = "etag_" + uuid.uuid4().hex[:12]

    mutation["status"] = "applied"
    mutation["updated_at"] = now_iso

    _save("calendar_event_mutations.json", mutations)
    _save("calendar_events.json", events)

    _log(200, None)
    return {"event": ev, "mutation": mutation}

def get_email(account_id, email_id, **_extra):
    import json, os, datetime, time, secrets, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0356000" if __import__("os").path.isdir("./environment_mix/0356000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _log(endpoint, status, used_account_id=None, error_code=None):
        request_logs = _load("request_logs.json")
        if not isinstance(request_logs, list):
            request_logs = []
        rid = "rlog_" + str(int(time.time() * 1000)) + "_" + secrets.token_hex(3)
        latency_ms = int((time.time() - t0) * 1000)
        request_logs.append({
            "id": rid,
            "service": "google_workspace",
            "endpoint": endpoint,
            "account_id": used_account_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": now_iso
        })
        _save("request_logs.json", request_logs)

    def _enforce_limits(endpoint, resolved_account_id):
        quotas = _load("quotas.json")
        if not isinstance(quotas, list):
            return None
        quota_cfg = None
        for q in quotas:
            if isinstance(q, dict) and q.get("service") == "google_workspace":
                quota_cfg = q
                break
        if not isinstance(quota_cfg, dict):
            return None

        request_logs = _load("request_logs.json")
        if not isinstance(request_logs, list):
            request_logs = []

        def _parse_ts(s):
            if not isinstance(s, str):
                return None
            s2 = s[:-1] if s.endswith("Z") else s
            try:
                dt = datetime.datetime.fromisoformat(s2)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt
            except Exception:
                return None

        rl = quota_cfg.get("rate_limit_per_minute")
        if isinstance(rl, int) and rl > 0:
            cutoff = now_dt - datetime.timedelta(seconds=60)
            cnt = 0
            for r in request_logs:
                if not isinstance(r, dict):
                    continue
                if r.get("service") != "google_workspace":
                    continue
                if r.get("endpoint") != endpoint:
                    continue
                if resolved_account_id and r.get("account_id") != resolved_account_id:
                    continue
                ts = _parse_ts(r.get("timestamp"))
                if ts and ts >= cutoff:
                    cnt += 1
            if cnt >= rl:
                return _err("RATE_LIMIT", "Rate limit exceeded; retry later.", retry_after_seconds=60)
        return None

    # validate (relax schema mismatch: datastore uses gmsg_ ids; also audit passed email address)
    if not isinstance(account_id, str) or not account_id:
        _log("get_email", "error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "account_id must be a non-empty string.", field="account_id")
    if not re.match(r"^gwsa_[0-9A-HJKMNP-TV-Z]{10,}$", account_id):
        _log("get_email", "error", account_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid account_id format.", field="account_id")
    if not isinstance(email_id, str) or not email_id:
        _log("get_email", "error", account_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "email_id must be a non-empty string.", field="email_id")
    # accept ids that look like gwem_/gmsg_ OR an email address (audit case)
    if not (re.match(r"^(gwem|gmsg)_[0-9A-HJKMNP-TV-Z]{10,}$", email_id) or ("@" in email_id)):
        _log("get_email", "error", account_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid email_id format.", field="email_id")

    accounts = _load("workspace_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    active_accounts = [a for a in accounts if isinstance(a, dict) and a.get("status") == "active" and isinstance(a.get("id"), str)]
    if not active_accounts:
        _log("get_email", "error", None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active Workspace account is configured for this service.")

    emails = _load("emails.json")
    if not isinstance(emails, list):
        emails = []

    # Find the email in a way that matches the datastore and avoids "first row" context bugs:
    # 1) Prefer exact (account_id, id)
    target = None
    for e in emails:
        if not isinstance(e, dict):
            continue
        if e.get("account_id") == account_id and e.get("id") == email_id:
            target = e
            break

    # 2) If the email_id is an email address, allow lookup by from/to for the specified account
    if target is None and "@" in email_id:
        for e in emails:
            if not isinstance(e, dict):
                continue
            if e.get("account_id") != account_id:
                continue
            if e.get("from_email") == email_id:
                target = e
                break
            to_list = e.get("to_emails")
            cc_list = e.get("cc_emails")
            bcc_list = e.get("bcc_emails")
            if isinstance(to_list, list) and email_id in to_list:
                target = e
                break
            if isinstance(cc_list, list) and email_id in cc_list:
                target = e
                break
            if isinstance(bcc_list, list) and email_id in bcc_list:
                target = e
                break

    # 3) If still not found, check whether the requested account_id is accessible (active); if not, try to resolve a working combo
    resolved_account_id = account_id if any(a.get("id") == account_id for a in active_accounts) else None
    if resolved_account_id is None:
        # cannot access requested account id under ambient auth
        _log("get_email", "error", None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Cannot access the requested account_id.", field="account_id")

    limit_err = _enforce_limits("get_email", resolved_account_id)
    if limit_err:
        _log("get_email", "error", resolved_account_id, limit_err["error"]["code"])
        return limit_err

    if target is None:
        _log("get_email", "error", resolved_account_id, "NOT_FOUND")
        return _err("NOT_FOUND", "Email not found for this account.", field="email_id")

    _log("get_email", "ok", resolved_account_id, None)
    return {"email": target}
